const std = @import("std"); const urln = @import("ut-urlz-norm.zig"); const tmfx = @import("nt-fetc-time.zig"); const vali = @import("sc-reco-vali.zig"); const chrs = @import("pa-char-dete.zig"); const inde = @import("st-page-inde.zig"); const pipe = @import("ru-page-fetc.zig"); const spen = @import("ru-spen-guar.zig"); const kill = @import("ru-kill-swit.zig"); const base = @import("nt-vend-base.zig"); const sqli = @import("st-stor-sqli.zig"); const cfgz = @import("cf-conf-load.zig"); const shel = @import("pa-shel-dete.zig"); const apiz = @import("ru-apiz-prob.zig"); const rend = @import("nt-brow-rend.zig"); const acct = @import("ru-acct-guar.zig"); const hits = @import("ru-hits-lear.zig"); const actz = @import("nt-brow-acts.zig"); const judg = @import("ru-tier-judg.zig"); const site = @import("cf-site-rule.zig");
const CF = .{ .perm = @as([]const []const u8, &.{ "NotText", "TooBig", "BadUrl", "BlockedHost", "CharUnsupported", "RedirectLoop", "TooManyRedirects" }) };
pub const Ladd = struct { gpaz: std.mem.Allocator, iozz: std.Io, conf: cfgz.Conf, dbzz: *sqli.Dbzz, dirz: []const u8, back: base.Backend, gozz: bool = false, priv: bool = false, geoz: []const u8 = "", wait: u32 = 0, sele: []const u8 = "", sess: ?*rend.Rndr = null, acts: actz.Acts = .{}, acct: []const u8 = "" };
fn shelNone(conf: cfgz.Conf) cfgz.Conf { var outp = conf; outp.shel_text_minz = 0; return outp; }
fn listFind(list: []const []const u8, name: []const u8) bool { for (list) |item| { if (std.mem.eql(u8, item, name)) return true; } return false; }
fn geozForz(self: *Ladd, host: []const u8) []const u8 { if (self.geoz.len > 0) return self.geoz; if (self.conf.geoz_host_over.map.get(host)) |code| return code; return self.conf.geoz_code_dflt; }
pub fn tierGetz(dbzz: *sqli.Dbzz, host: []const u8) !?struct { tier: i64, timz: i64, t1fz: i64 } { var stmt = try dbzz.prep("SELECT tier,timz,t1fz FROM tier WHERE host=?1;"); defer stmt.fini(); try stmt.bindText(1, host); if (!try stmt.step()) return null; return .{ .tier = stmt.colzIntz(0), .timz = stmt.colzIntz(1), .t1fz = stmt.colzIntz(2) }; }
pub fn tierSetz(dbzz: *sqli.Dbzz, host: []const u8, tier: i64, vend: []const u8, timz: i64) !void { var stmt = try dbzz.prep("INSERT INTO tier(host,tier,vend,timz) VALUES(?1,?2,?3,?4) ON CONFLICT(host) DO UPDATE SET tier=?2,vend=?3,timz=?4;"); defer stmt.fini(); try stmt.bindText(1, host); try stmt.bindIntz(2, tier); try stmt.bindText(3, vend); try stmt.bindIntz(4, timz); _ = try stmt.step(); }
pub fn tierOnez(dbzz: *sqli.Dbzz, host: []const u8, timz: i64) !void { var stmt = try dbzz.prep("INSERT INTO tier(host,tier,vend,timz,t1fz) VALUES(?1,1,'',?2,0) ON CONFLICT(host) DO UPDATE SET t1fz=0,timz=?2;"); defer stmt.fini(); try stmt.bindText(1, host); try stmt.bindIntz(2, timz); _ = try stmt.step(); }
pub fn tierFail(dbzz: *sqli.Dbzz, host: []const u8, timz: i64) !void { var stmt = try dbzz.prep("INSERT INTO tier(host,tier,vend,timz,t1fz) VALUES(?1,2,'',?2,1) ON CONFLICT(host) DO UPDATE SET t1fz=t1fz+1,timz=?2;"); defer stmt.fini(); try stmt.bindText(1, host); try stmt.bindIntz(2, timz); _ = try stmt.step(); }
fn locaTryz(self: *Ladd, aren: std.mem.Allocator, norm: []const u8, urlz: []const u8, prev: ?inde.Rowz) !?pipe.Outc { const sess = self.sess orelse return null; if (!sess.avai() or !self.conf.brow_enab) return null; sess.conf = self.conf; const nowz = pipe.nowzMill(self.iozz); const rndz = sess.render(aren, urlz, self.wait, self.sele, self.acts) catch |err3| { try logzVend(self, norm, 0, .plain, "brow", 0, 0, @errorName(err3), nowz); return null; }; const got2: pipe.Gotz = .{ .code = 200, .ctyp = "text/html; charset=utf-8", .body = rndz.html, .vend = "brow", .tier = 1 }; const judz = try judg.judgPage(aren, got2, prev, shelNone(self.conf)); if (judz != .good) { try logzVend(self, norm, 200, .plain, "brow", 0, 0, "local browser page not good, climbing", nowz); return null; } var out2 = try pipe.pageSave(aren, self.iozz, self.conf, self.dbzz, self.dirz, norm, prev, got2); out2.vend = "brow"; return out2; }
fn acctFetc(self: *Ladd, aren: std.mem.Allocator, norm: []const u8, urlz: []const u8, prev: ?inde.Rowz) !pipe.Outc { if (!self.conf.logi_mode_enab or !self.conf.brow_enab) return error.NotConfigured; const sess = self.sess orelse return error.NoBrowser; if (!sess.avai()) return error.NoBrowser; sess.conf = self.conf; const nowz = pipe.nowzMill(self.iozz); const tkzz = try acct.acctTake(self.dbzz, self.acct, nowz, self.conf.acct_page_maxz, @as(u64, self.conf.rate_host_seco) * 1000 * self.conf.acct_gapz_mult); if (tkzz.wait > 0) std.Io.sleep(self.iozz, .fromMilliseconds(@intCast(tkzz.wait)), .awake) catch {}; const rndz = sess.render(aren, urlz, self.wait, self.sele, self.acts) catch |err3| { try logzVend(self, norm, 0, .plain, "acct", 0, 0, @errorName(err3), nowz); return error.BrowFail; }; if (std.ascii.findIgnoreCase(rndz.html, "type=\"password\"") != null) { try acct.acctWall(self.dbzz, self.acct, nowz); try logzVend(self, norm, 200, .plain, "acct", 0, 0, "login wall: session expired, stopped, no retry", nowz); return error.LoginWall; } const got2: pipe.Gotz = .{ .code = 200, .ctyp = "text/html; charset=utf-8", .body = rndz.html, .vend = "brow", .tier = 1 }; if ((try judg.judgPage(aren, got2, prev, shelNone(self.conf))) != .good) { try logzVend(self, norm, 200, .plain, "acct", 0, 0, "page not good", nowz); return error.BrowFail; } var out2 = try pipe.pageSave(aren, self.iozz, self.conf, self.dbzz, self.dirz, norm, prev, got2); out2.vend = "brow"; return out2; }
fn permOkay(name: []const u8) bool { for (CF.perm) |item| if (std.mem.eql(u8, item, name)) return true; return false; }
fn logzVend(self: *Ladd, urlz: []const u8, code: i64, mode: base.Mode, vend: []const u8, cred: u32, micr: u64, note: []const u8, nowz: i64) !void { try inde.logzAddz(self.dbzz, .{ .urlz = urlz, .code = code, .tier = @backingInt(mode), .vend = vend, .cred = cred, .micr = @intCast(micr), .robo = "none", .timz = nowz, .note = note }); }
pub fn laddFetc(self: *Ladd, aren: std.mem.Allocator, urlz: []const u8) !pipe.Outc { const norm = try urln.urlzNorm(aren, urlz); const part = try urln.urlzSpli(norm); const prev = try inde.pageGetz(self.dbzz, aren, norm); const savc = self.conf; const savw = self.wait; const sava = self.acts; const savs = self.sele; defer { self.conf = savc; self.wait = savw; self.acts = sava; self.sele = savs; } self.conf = site.siteConf(aren, savc, part.host, part.path) catch savc; if (self.wait == 0) self.wait = self.conf.brow_wait_msec; if (self.sele.len == 0) self.sele = self.conf.brow_sele_wait; if (!self.acts.any()) { var acta: actz.Acts = .{ .clic = self.conf.brow_clic_text }; if (self.conf.brow_step_file.len > 0) { const txtz = std.Io.Dir.cwd().readFileAlloc(self.iozz, self.conf.brow_step_file, aren, .limited(1 << 20)) catch return error.BadConfig; acta.ste2 = actz.stepRead(aren, txtz, self.conf.brow_step_maxz) catch return error.BadConfig; } self.acts = acta; } const now0 = pipe.nowzMill(self.iozz); if (self.acct.len > 0) return acctFetc(self, aren, norm, urlz, prev); const wan2 = self.acts.any() or self.wait > 0 or self.sele.len > 0 or std.mem.eql(u8, self.conf.tier_star, "brow"); if (wan2 and geozForz(self, part.host).len == 0) { if (self.sess != null and self.sess.?.avai() and self.conf.brow_enab) { if (try locaTryz(self, aren, norm, urlz, prev)) |out2| return out2; if (self.acts.any()) return error.BrowFail; } else if (self.acts.any()) return error.NoBrowser; } var start: i64 = 2; var ski2 = false; if (try tierGetz(self.dbzz, part.host)) |hitz| { start = @max(hitz.tier, 2); if (start > 2 and now0 - hitz.timz > @as(i64, self.conf.tier_ages) * 86400000) start -= 1; ski2 = hitz.t1fz >= self.conf.tier_t1fz; } const geoz = geozForz(self, part.host); if (geoz.len > 0 or listFind(self.conf.tier_skip_list, "own")) ski2 = true; if (self.wait > 0 or self.sele.len > 0) start = @max(start, 3); if (std.mem.eql(u8, self.conf.tier_star, "plain")) start = @max(start, 2); if (std.mem.eql(u8, self.conf.tier_star, "rend")) start = @max(start, 3); if (std.mem.eql(u8, self.conf.tier_star, "prem")) start = @max(start, 4);
if (!ski2) { const cond: @import("nt-fetc-owns.zig").Cond = if (prev) |row2| .{ .etag = row2.etag, .lmod = row2.lmod } else .{}; if (tmfx.fetcTime(self.gpaz, self.iozz, urlz, try pipe.optsMake(aren, self.conf, self.priv), cond)) |resp| { var res4 = resp; defer res4.free(self.gpaz); const got2: pipe.Gotz = .{ .code = res4.code, .ctyp = res4.ctyp, .body = res4.body, .etag = res4.etag, .lmod = res4.lmod, .retr = res4.retr }; const judz = try judg.judgPage(aren, got2, prev, self.conf); if (judz == .good or judz == .gone) { try tierOnez(self.dbzz, part.host, now0); return pipe.pageSave(aren, self.iozz, self.conf, self.dbzz, self.dirz, norm, prev, got2); }
if (judz == .shel) { if (self.conf.apiz_prob_enab) { if (try apiz.apizProb(self.gpaz, aren, self.iozz, self.conf, self.dbzz, self.priv, norm, try chrs.utf8Conv(aren, chrs.charFind(got2.ctyp, got2.body), got2.body), now0)) |hitz| { try tierOnez(self.dbzz, part.host, now0); return pipe.pageSave(aren, self.iozz, self.conf, self.dbzz, self.dirz, norm, prev, hitz); } } if (try locaTryz(self, aren, norm, urlz, prev)) |out2| return out2; start = @max(start, 3); try logzVend(self, norm, res4.code, .plain, "", 0, 0, "own GET thin shell, no api, climbing to render", now0); try tierFail(self.dbzz, part.host, now0); }
else { try logzVend(self, norm, res4.code, .plain, "", 0, 0, "own GET blocked, climbing", now0); try tierFail(self.dbzz, part.host, now0); } } else |err3| { if (permOkay(@errorName(err3)) or !std.mem.eql(u8, @errorName(err3), "NeedVendor")) return err3; try logzVend(self, norm, 0, .plain, "", 0, 0, "own GET needs vendor", now0); try tierFail(self.dbzz, part.host, now0); } }
var down = @as([3]bool, @splat(false)); var trie: u8 = 0; const mod2 = [_]base.Mode{ .plain, .rend, .prem };
for (mod2) |mode| { if (@backingInt(mode) < start or @backingInt(mode) > self.conf.tier_maxz) continue; var pick: ?base.Vend = null; var cost: u32 = 0; var deci: spen.Deci = .{ .okay = false };
const ordr = try hits.hitsOrde(self.dbzz, aren, part.host, self.conf.vend_orde, @backingInt(mode), pipe.nowzMill(self.iozz)); for (ordr) |name| { const vend = base.vendFind(name) orelse continue; if (down[@backingInt(vend)] or listFind(self.conf.vend_bann_list, name)) continue; const rqzz: base.Requ = .{ .urlz = urlz, .mode = mode, .geoz = geoz, .wait = self.wait, .sele = self.sele }; cost = base.credRequ(vend, rqzz); if (self.conf.capz_cred_pagz > 0 and cost > self.conf.capz_cred_pagz) continue; const decz = try spen.spenChek(self.dbzz, self.conf, vend, cost, pipe.nowzMill(self.iozz), self.gozz); if (!decz.okay) { if (std.mem.eql(u8, decz.why2, "kill switch on")) return error.KillOn; down[@backingInt(vend)] = true; continue; } pick = vend; deci = decz; break; }
const vend = pick orelse { if (trie == 0) return error.OverCap; return error.Blocked; }; trie += 1; const nowz = pipe.nowzMill(self.iozz); const res4 = self.back.call(self.back.ctx2, aren, self.iozz, vend, .{ .urlz = urlz, .mode = mode, .geoz = geoz, .wait = self.wait, .sele = self.sele }) catch |err3| { try logzVend(self, norm, 0, mode, base.vendName(vend), 0, 0, @errorName(err3), nowz); try hits.hitsRecz(self.dbzz, part.host, base.vendName(vend), @backingInt(mode), false, 0, 0, nowz); down[@backingInt(vend)] = true; continue; };
if (res4.errz.len > 0) { try logzVend(self, norm, res4.code, mode, base.vendName(vend), 0, 0, res4.errz, nowz); try hits.hitsRecz(self.dbzz, part.host, base.vendName(vend), @backingInt(mode), false, 0, 0, nowz); down[@backingInt(vend)] = true; continue; }
const micr: u64 = if (deci.paid) deci.micr else 0; if (res4.cred > 0) try spen.spenRecz(self.dbzz, vend, res4.cred, micr, nowz); const got2: pipe.Gotz = .{ .code = res4.code, .ctyp = res4.ctyp, .body = res4.body, .tier = @backingInt(mode), .vend = base.vendName(vend), .cred = @intCast(res4.cred), .micr = @intCast(micr) }; const judz = try judg.judgPage(aren, got2, prev, self.conf);
if (judz == .block or (judz == .shel and mode == .plain)) { try hits.hitsRecz(self.dbzz, part.host, base.vendName(vend), @backingInt(mode), false, @intCast(res4.cred), @intCast(micr), nowz); try logzVend(self, norm, res4.code, mode, base.vendName(vend), res4.cred, micr, "vendor result blocked, climbing", nowz); continue; }
try hits.hitsRecz(self.dbzz, part.host, base.vendName(vend), @backingInt(mode), true, @intCast(res4.cred), @intCast(micr), nowz); var outc = try pipe.pageSave(aren, self.iozz, self.conf, self.dbzz, self.dirz, norm, prev, got2); outc.tier = @backingInt(mode); outc.vend = base.vendName(vend); outc.cred = res4.cred; outc.micr = micr; try tierSetz(self.dbzz, part.host, @backingInt(mode), base.vendName(vend), nowz); return outc; }
if (trie == 0) return error.OverCap; return error.Blocked; }
